function event(id: string, occurredAt: string): ActivityEvent {
  return {
    id: id as ActivityId,
    orgId: "org_1" as OrgId,
    action: "issue.created",
    actorId: "usr_1" as UserId,
    subjectKind: "issue",
    subjectId: "iss_1",
    projectId: null,
    summary: `event ${id}`,
    metadata: {},
    occurredAt: toIsoTimestamp(occurredAt),
  };
}

