sub(p, """export async function updateProject(
  input: UpdateProjectInput,
): Promise<Project> {""", """/**
 * What a new project's initial issue is made of. Number, author, assignee,
 * parent and the progress timestamps are not the caller's to choose here —
 * `insertProjectWithIssues` fills them in.
 */
export type InitialIssue = Pick<
  CreateIssueInput,
  | "title"
  | "description"
  | "status"
  | "priority"
  | "estimate"
  | "dueAt"
  | "labelIds"
>;

/** Rows per multi-row insert, kept well under SQLite's bound-parameter cap. */
const ISSUE_INSERT_BATCH = 50;
const LABEL_INSERT_BATCH = 300;

/**
 * Inserts a project together with a first batch of issues, in one
 * transaction: either the project and every issue exist afterwards or none of
 * them do. The project row is written exactly as `insertProject` writes it
 * (unique slug, `active`, no start date). The issues are numbered from 1 in
 * the order given, authored by `authorId`, unassigned, without a parent and
 * with no start or completion time.
 */
export async function insertProjectWithIssues(
  input: CreateProjectInput,
  initialIssues: readonly InitialIssue[],
  authorId: UserId,
): Promise<Project> {
  return getDb().transaction((tx) => {
    const taken = tx
      .select({ slug: projects.slug })
      .from(projects)
      .where(orgPredicate(projects.orgId, input.orgId))
      .all()
      .map((row) => row.slug);
    const stamp = toIsoTimestamp(new Date());

    const project = tx
      .insert(projects)
      .values({
        id: newId(),
        orgId: input.orgId,
        name: input.name,
        slug: uniqueSlug(input.slug, taken),
        key: input.key,
        description: input.description,
        visibility: input.visibility,
        status: "active",
        leadId: input.leadId,
        color: input.color,
        startsAt: null,
        targetDate: input.targetDate,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    const issueRows = initialIssues.map((issue, index) => ({
      id: newId(),
      orgId: input.orgId,
      projectId: project.id,
      number: index + 1,
      title: issue.title,
      description: issue.description,
      status: issue.status,
      priority: issue.priority,
      authorId,
      assigneeId: null,
      parentId: null,
      estimate: issue.estimate,
      dueAt: issue.dueAt,
      startedAt: null,
      completedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    }));

    const labelRows = issueRows.flatMap((row, index) =>
      [...new Set(initialIssues[index]?.labelIds ?? [])].map((labelId) => ({
        orgId: input.orgId,
        issueId: row.id,
        labelId,
      })),
    );

    for (let at = 0; at < issueRows.length; at += ISSUE_INSERT_BATCH) {
      tx.insert(issues)
        .values(issueRows.slice(at, at + ISSUE_INSERT_BATCH))
        .run();
    }
    for (let at = 0; at < labelRows.length; at += LABEL_INSERT_BATCH) {
      tx.insert(issueLabels)
        .values(labelRows.slice(at, at + LABEL_INSERT_BATCH))
        .run();
    }

    return toProject(project);
  });
}

export async function updateProject(
  input: UpdateProjectInput,
): Promise<Project> {""")
