  // one creation is: issues already there (none) plus the ones being added.
  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}: cloning ${source.key} would copy ${sourceIssues.length} issues`,
    );
  }

  const status = defaultIssueStatus(org.settings.defaultIssueStatus);

  const clone = await projectRepo.insertProjectWithIssues(
    {
      orgId: input.orgId,
      name: input.name,
      slug: input.slug,
      key: input.key,
      description: source.description,
      visibility: source.visibility,
      leadId: source.leadId,
      color: source.color,
      targetDate: null,
    },
    sourceIssues.map((issue) => ({
      title: issue.title,
      description: issue.description,
      status,
      priority: issue.priority,
      estimate: issue.estimate,
      dueAt: issue.dueAt,
      labelIds: [...issue.labelIds],
    })),
    actor.userId,
  );

  const cloned: TaskflowEventPayload<"project.cloned"> = {
    ...actorEnvelope(actor),
    projectId: clone.id,
    sourceProjectId: source.id,
    issuesCopied: sourceIssues.length,
  };
