/**
 * Cloning a project (ADR 0012): what is copied, what is reset, how the batch
 * is gated and how the clone is announced.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { activityFilterSchema } from "@/schemas/activity";
import { cloneProjectSchema } from "@/schemas/project";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CloneProjectInput } from "@/schemas/project";
import type { IsoTimestamp, ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function cloneInput(
  tenant: Tenant,
  overrides: Partial<CloneProjectInput> = {},
): CloneProjectInput {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name: "Release train 2",
    slug: "release-2",
    key: "REL2",
    includeIssues: true,
    ...overrides,
  };
}

/** Seeds live issues straight through the repository, numbered from `from`. */
async function seedIssues(tenant: Tenant, count: number, from = 1): Promise<void> {
  for (let offset = 0; offset < count; offset += 1) {
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: `Seeded issue ${from + offset}`,
      }),
      tenant.userIds.member,
      from + offset,
    );
  }
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  unregisterEventHandlers();
});

afterAll(() => {
  cleanup();
});

describe("schemas/project cloneProjectSchema", () => {
  it("includes the issues unless told otherwise", () => {
    const base = {
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP",
      name: "Release train 2",
      slug: "release-2",
      key: "REL2",
    };

    expect(cloneProjectSchema.parse(base).includeIssues).toBe(true);
    expect(
      cloneProjectSchema.parse({ ...base, includeIssues: false }).includeIssues,
    ).toBe(false);
    expect(cloneProjectSchema.safeParse({ ...base, slug: "Release" }).success).toBe(false);
    expect(cloneProjectSchema.safeParse({ ...base, key: "rel" }).success).toBe(false);
  });
});

describe("services/project-service cloneProject", () => {
  it("creates a fresh project from the source's settings", async () => {
    const tenant = await createTenant("clonefields", "growth");
    const source = await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      description: "Every release, the same checklist",
      visibility: "private",
      status: "paused",
      color: "#112233",
      targetDate: "2026-06-01T00:00:00.000Z" as IsoTimestamp,
    });

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant),
    );

    expect(clone).toMatchObject({
      orgId: tenant.org.id,
      name: "Release train 2",
      slug: "release-2",
      key: "REL2",
      description: "Every release, the same checklist",
      visibility: "private",
      color: "#112233",
      leadId: source.leadId,
      status: "active",
      startsAt: null,
      targetDate: null,
      archivedAt: null,
    });
    expect(clone.id).not.toBe(source.id);
    expect(await projectRepo.findProjectById(tenant.org.id, clone.id)).toEqual(clone);

    // The source is left exactly as it was.
    expect(await projectRepo.findProjectById(tenant.org.id, source.id)).toEqual(source);
  });

  it("suffixes a taken slug and leaves the key to the caller", async () => {
    const tenant = await createTenant("cloneslug", "growth");

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { name: "Anything At All", slug: "platform", key: "ZZ9" }),
    );
    expect(clone.slug).toBe("platform-2");
    expect(clone.key).toBe("ZZ9");

    // A key that is already taken is not repaired, and nothing is created.
    const before = await projectRepo.countProjects(tenant.org.id);
    await expect(
      projectService.cloneProject(
        tenant.actors.member,
        cloneInput(tenant, { slug: "third", key: "PLAT" }),
      ),
    ).rejects.toThrow();
    expect(await projectRepo.countProjects(tenant.org.id)).toBe(before);
  });

  it("copies live issues as a fresh start, renumbered in source order", async () => {
    const tenant = await createTenant("cloneissues", "growth");
    const { member, admin } = tenant.actors;
    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "release",
      color: "#94a3b8",
      description: null,
    });

    const first = await issueService.createIssue(member, {
      ...issueInput(tenant.org.id, tenant.project.id, {
        title: "First",
        assigneeId: tenant.userIds.admin,
        dueAt: "2026-07-01T00:00:00.000Z",
      }),
      description: "Do the first thing",
      priority: "high",
      estimate: 5,
      labelIds: [label.id],
    });
    const archived = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Archived" }),
    );
    const third = await issueService.createIssue(member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Third" }),
      parentId: first.id,
    });

    await issueService.changeIssueStatus(member, {
      orgId: tenant.org.id,
      issueId: first.id,
      status: "in_progress",
    });
    await issueService.changeIssueStatus(member, {
      orgId: tenant.org.id,
      issueId: third.id,
      status: "done",
    });
    await issueService.archiveIssue(member, tenant.org.id, archived.id);
    await commentService.createComment(member, {
      orgId: tenant.org.id,
      issueId: first.id,
      body: "A conversation, not work",
      parentId: null,
      mentionedUserIds: [],
    });

    const sourceBefore = await issueRepo.listLiveIssuesByNumber(
      tenant.org.id,
      tenant.project.id,
    );

    const clone = await projectService.cloneProject(admin, cloneInput(tenant));

    const copies = await issueRepo.listLiveIssuesByNumber(tenant.org.id, clone.id);
    expect(
      await issueRepo.countIssues(tenant.org.id, clone.id, { includeArchived: true }),
    ).toBe(2);
    expect(copies.map((issue) => [issue.number, issue.title])).toEqual([
      [1, "First"],
      [2, "Third"],
    ]);

    expect(copies[0]).toMatchObject({
      projectId: clone.id,
      title: "First",
      description: "Do the first thing",
      priority: "high",
      estimate: 5,
      dueAt: "2026-07-01T00:00:00.000Z",
      labelIds: [label.id],
      status: "backlog",
      assigneeId: null,
      authorId: tenant.userIds.admin,
      parentId: null,
      startedAt: null,
      completedAt: null,
      archivedAt: null,
    });
    expect(copies[1]).toMatchObject({
      status: "backlog",
      assigneeId: null,
      authorId: tenant.userIds.admin,
      parentId: null,
      startedAt: null,
      completedAt: null,
    });

    // The copy read back through the ordinary lookup carries its labels too.
    const reread = await issueRepo.findIssueById(tenant.org.id, copies[0]!.id);
    expect(reread?.labelIds).toEqual([label.id]);

    // Comments stay behind.
    for (const copy of copies) {
      expect(await commentRepo.countComments(tenant.org.id, copy.id)).toBe(0);
    }

    // The source and its issues are untouched.
    expect(
      await issueRepo.listLiveIssuesByNumber(tenant.org.id, tenant.project.id),
    ).toEqual(sourceBefore);
    expect(await commentRepo.countComments(tenant.org.id, first.id)).toBe(1);

    // Issues created in the clone afterwards continue the numbering.
    const next = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, clone.id, { title: "After the clone" }),
    );
    expect(next.number).toBe(3);
  });

  it("starts the copies in the workspace's default issue status", async () => {
    const tenant = await createTenant("clonestatus", "growth");
    const { getDb, organizations } = await import("@/server/db");
    const { eq } = await import("drizzle-orm");
    getDb()
      .update(organizations)
      .set({ defaultIssueStatus: "todo" })
      .where(eq(organizations.id, tenant.org.id))
      .run();

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Was in review" }),
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_review",
    });

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant),
    );
    const copies = await issueRepo.listLiveIssuesByNumber(tenant.org.id, clone.id);
    expect(copies.map((copy) => copy.status)).toEqual(["todo"]);
  });

  it("walks every live issue, not just one page", async () => {
    const tenant = await createTenant("clonepages", "growth");
    await seedIssues(tenant, 230);

    const seen = capture("project.cloned");
    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant),
    );

    expect(await issueRepo.countIssues(tenant.org.id, clone.id)).toBe(230);
    const copies = await issueRepo.listLiveIssuesByNumber(tenant.org.id, clone.id);
    expect(copies.map((issue) => issue.number)).toEqual(
      Array.from({ length: 230 }, (_, index) => index + 1),
    );
    expect(copies[229]?.title).toBe("Seeded issue 230");
    expect(seen[0]?.issuesCopied).toBe(230);
  });

  it("leaves the issues behind when asked", async () => {
    const tenant = await createTenant("clonebare", "growth");
    await seedIssues(tenant, 3);

    const seen = capture("project.cloned");
    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { includeIssues: false }),
    );

    expect(
      await issueRepo.countIssues(tenant.org.id, clone.id, { includeArchived: true }),
    ).toBe(0);
    expect(seen[0]?.issuesCopied).toBe(0);
  });

  it("refuses the whole clone when the batch exceeds the issue quota", async () => {
    const tenant = await createTenant("clonequota", "free");
    await seedIssues(tenant, 101);

    const seen = capture("project.cloned");
    await expect(
      projectService.cloneProject(tenant.actors.member, cloneInput(tenant)),
    ).rejects.toThrow(/allows no more issues/);

    expect(await projectRepo.countProjects(tenant.org.id, { includeArchived: true })).toBe(1);
    expect(await projectRepo.findProjectBySlug(tenant.org.id, "release-2")).toBeNull();
    expect(seen).toHaveLength(0);

    // Archived issues are not copied, so they do not count against the batch.
    const last = await issueRepo.findIssueByNumber(tenant.org.id, tenant.project.id, 101);
    await issueRepo.archiveIssue(tenant.org.id, last!.id);

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant),
    );
    expect(await issueRepo.countIssues(tenant.org.id, clone.id)).toBe(100);
  });

  it("applies the project quota like a creation", async () => {
    const tenant = await createTenant("cloneprojquota", "free");
    await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    await expect(
      projectService.cloneProject(
        tenant.actors.member,
        cloneInput(tenant, { name: "Third", slug: "third", key: "THI" }),
      ),
    ).rejects.toThrow(/allows 2 projects/);
    expect(await projectRepo.countProjects(tenant.org.id)).toBe(2);
  });

  it("is gated on reading the source and creating a project", async () => {
    const tenant = await createTenant("clonegates", "growth");
    const other = await createTenant("clonegates-other", "growth");

    await expect(
      projectService.cloneProject(tenant.actors.viewer, cloneInput(tenant)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      projectService.cloneProject(other.actors.owner, cloneInput(tenant)),
    ).rejects.toBeInstanceOf(TenantScopeError);

    // Another workspace's project is not a project of this workspace.
    await expect(
      projectService.cloneProject(
        tenant.actors.member,
        cloneInput(tenant, { projectId: other.project.id }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.cloneProject(
        tenant.actors.member,
        cloneInput(tenant, { projectId: "01HZZZNNNNNNNNNNNNNNNNNNNN" as ProjectId }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await expect(
      projectService.cloneProject(tenant.actors.member, cloneInput(tenant)),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect(await projectRepo.countProjects(tenant.org.id, { includeArchived: true })).toBe(1);
  });

  describe.each([
    { wiring: "with the event registry attached", attach: true },
    { wiring: "with nothing listening", attach: false },
  ])("announcing, $wiring", ({ attach }) => {
    it("publishes one project.cloned and leaves audit, search and meters current", async () => {
