      );
      await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Quokka rollout" }),
      );

      const cloned = capture("project.cloned");
      const created = capture("project.created");
      const issueCreated = capture("issue.created");
      const usageBefore = await usageRepo.getUsage(tenant.org.id);

      const clone = await projectService.cloneProject(
        tenant.actors.admin,
        cloneInput(tenant, { name: "Wombat release" }),
      );

      expect(cloned).toHaveLength(1);
      expect(cloned[0]).toMatchObject({
        orgId: tenant.org.id,
        actorId: tenant.userIds.admin,
        projectId: clone.id,
        sourceProjectId: tenant.project.id,
        issuesCopied: 2,
      });
      expect(cloned[0]?.occurredAt).toEqual(expect.any(String));
      expect(created).toHaveLength(0);
      expect(issueCreated).toHaveLength(0);

      // Exactly one audit entry, under the new project.
      const audit = await activityRepo.listActivity(
        activityFilterSchema.parse({
          orgId: tenant.org.id,
          action: ["project.cloned"],
          limit: 25,
          cursor: null,
        }),
      );
      expect(audit.items).toHaveLength(1);
      expect(audit.items[0]).toMatchObject({
        action: "project.cloned",
        actorId: tenant.userIds.admin,
        subjectKind: "project",
        subjectId: clone.id,
        projectId: clone.id,
        metadata: { sourceProjectId: tenant.project.id, issuesCopied: 2 },
      });
      expect(
        await activityRepo.listActivityForSubject(tenant.org.id, "project", clone.id),
      ).toHaveLength(1);

      // The clone and its issues are searchable at once.
      const projectHits = await searchService.search(tenant.actors.member, {
